issue-parameter-present-without-pr.body:
const params = new URLSearchParams();
params.set('issue', value.issue);
if (value.fetch !== undefined) params.set('fetch', value.fetch);
if (value.gh !== undefined) params.set('gh', value.gh);
if (value.d !== undefined) params.set('d', value.d);
if (value.s !== undefined) params.set('s', value.s);

const result = selectAdapters(params);
expect(result.adapter).toBeInstanceOf(UrlParamAdapter);
expect(result.backend).toBeInstanceOf(GitForgeIssueBackend);
const backend = result.backend as GitForgeIssueBackend;
expect(backend.issue).toBe(value.issue);
expect(backend.forge).toBeInstanceOf(GitHubForge);

